// Normalise l'entree du formulaire et fabrique un identifiant de dossier.
const m = $json.body ?? $json;
const url = (m.url ?? '').trim().replace(/\/$/, '');
if (!/^https?:\/\//.test(url)) {
  throw new Error("URL invalide : indiquez l'adresse complete, https:// compris.");
}
const metierSlug = (m.metier ?? 'cabinet')
  .toLowerCase()
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .replace(/[^a-z0-9]+/g, '_')
  .replace(/^_+|_+$/g, '');
const dossier = metierSlug + '_' + $now.toFormat('yyyyLLdd') + '_' + $execution.id;
return [{
  json: {
    dossier,
    url,
    domaine: url.replace(/^https?:\/\//, '').split('/')[0],
    metier: m.metier ?? 'notaire',
    ville: m.ville ?? 'Nantes',
    email: m.email ?? null,
    recuA: $now.toISO(),
  },
}];

// Extrait les signaux mesurables AVANT de faire parler un modele.
// Les agents raisonnent sur des faits, pas sur du HTML brut.
const html = $json.body ?? '';
const head = html.slice(0, 40000);
const pick = (re) => (head.match(re)?.[1] ?? '').replace(/\s+/g, ' ').trim();
const all = (re) => [...html.matchAll(re)].map(x => x[1].replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim());
const texte = html
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<[^>]+>/g, ' ');
const demande = $('Normaliser la demande').item.json;
const faits = {
  statut: $json.statusCode ?? 0,
  https: demande.url.startsWith('https://'),
  poidsKo: Math.round(html.length / 1024),
  title: pick(/<title[^>]*>([\s\S]*?)<\/title>/i),
  metaDescription: pick(/<meta[^>]+name=["']description["'][^>]+content=["']([^"']*)/i),
  viewport: /name=["']viewport["']/i.test(head),
  h1: all(/<h1[^>]*>([\s\S]*?)<\/h1>/gi),
  h2: all(/<h2[^>]*>([\s\S]*?)<\/h2>/gi).slice(0, 12),
  nbImagesSansAlt: (html.match(/<img(?![^>]*\balt=)/gi) ?? []).length,
  formulaire: /<form/i.test(html),
  telCliquable: /href=["']tel:/i.test(html),
  mailto: /href=["']mailto:/i.test(html),
  priseRdvEnLigne: /(doctolib|calendly|rendez-?vous en ligne|prendre rendez-?vous)/i.test(texte),
  mentionsLegales: /mentions l[ee]gales/i.test(texte),
  rgpd: /(politique de confidentialit[ee]|rgpd|donn[ee]es personnelles)/i.test(texte),
  cookiesBanniere: /(tarteaucitron|axeptio|cookieconsent|didomi)/i.test(html),
  motsVisibles: texte.split(' ').filter(Boolean).length,
};
return [{ json: { ...demande, faits } }];

